                tick={{ fill: "#334155", fontSize: 12 }}
              />
              <Tooltip
                formatter={(value, name) => [
                  `${value}%`,
                  name === "insuredPayoutSharePct" ? "Insured payout" : "Cash residual",
                ]}
              />
              <Legend />
              <Bar
                dataKey="insuredPayoutSharePct"
                name="Insured payout"
                stackId="a"
                fill={COLORS.insured}
              />
              <Bar
                dataKey="cashResidualSharePct"
                name="Cash / SIR residual"
                stackId="a"
                fill={COLORS.cash}
                radius={[0, 4, 4, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        ) : null}

        {panel === "funding-mix" ? (
          <div className="grid gap-6 lg:grid-cols-2">
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={FUNDING_MIX_ILLUSTRATION}
                  dataKey="sharePct"
                  nameKey="short"
                  cx="50%"
                  cy="50%"
                  innerRadius={58}
                  outerRadius={100}
                  paddingAngle={2}
                  label={({ short, sharePct }) => `${short} ${sharePct}%`}
                >
                  {FUNDING_MIX_ILLUSTRATION.map((s) => (
                    <Cell
                      key={s.short}
                      fill={s.short === "Insured" ? COLORS.insured : COLORS.cash}
                    />
                  ))}
                </Pie>
                <Tooltip formatter={(v) => [`${v}%`, "Share of incident cost"]} />
