            </ResponsiveContainer>
            <ResponsiveContainer width="100%" height={300}>
              <ComposedChart data={naicRows} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis dataKey="year" tick={{ fill: "#64748b", fontSize: 12 }} />
                <YAxis
                  yAxisId="left"
                  tick={{ fill: "#64748b", fontSize: 12 }}
                  tickFormatter={(v) => `$${v}B`}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  domain={[0, 80]}
                  tick={{ fill: "#64748b", fontSize: 12 }}
                  tickFormatter={(v) => `${v}%`}
                />
                <Tooltip />
                <Legend />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="dwp"
                  name="Domestic DWP ($B)"
                  fill={COLORS.naic}
                  stroke={COLORS.naic}
                  fillOpacity={0.25}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="lossRatio"
                  name="Loss+DCC %"
                  stroke={COLORS.cash}
                  strokeWidth={2}
                  connectNulls={false}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        ) : null}

        {panel === "cost-stack" ? (
          <ResponsiveContainer width="100%" height={360}>
            <BarChart data={stackRows} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
              <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
              <XAxis dataKey="year" tick={{ fill: "#64748b", fontSize: 12 }} />
              <YAxis
                tick={{ fill: "#64748b", fontSize: 12 }}
                tickFormatter={(v) =>
                  stackMode === "dollars" ? `$${v}M` : `${v}%`
                }
              />
              <Tooltip
                formatter={(value, name) => [
                  stackMode === "dollars"
                    ? `$${Number(value).toFixed(2)}M`
                    : `${value}%`,
                  name === "ransom" ? "Median ransom" : "Recovery excl. ransom",
                ]}
              />
              <Legend />
              <Bar
                dataKey="ransom"
                name="Ransom"
                stackId="s"
                fill={COLORS.ransom}
              />
              <Bar
                dataKey="recovery"
                name="Recovery"
                stackId="s"
                fill={COLORS.recovery}
                radius={[4, 4, 0, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        ) : null}

        {panel === "size-scatter" ? (
          <ResponsiveContainer width="100%" height={360}>
            <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 12 }}>
              <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
              <XAxis
                type="number"
                dataKey="revenueProxyUsdB"
                name="Revenue proxy"
                tick={{ fill: "#64748b", fontSize: 12 }}
                tickFormatter={(v) => `$${v}B`}
                label={{
                  value: "Avg revenue proxy ($B)",
                  position: "insideBottom",
                  offset: -4,
                  fill: "#94a3b8",
                  fontSize: 11,
                }}
              />
              <YAxis
                type="number"
                dataKey="insuredSharePct"
                name="Insured share"
                domain={[0, 80]}
                tick={{ fill: "#64748b", fontSize: 12 }}
                unit="%"
                label={{
                  value: "Insured payout share",
                  angle: -90,
                  position: "insideLeft",
                  fill: "#94a3b8",
                  fontSize: 11,
                }}
              />
              <ZAxis type="number" dataKey="claimWeightPct" range={[80, 400]} />
              <Tooltip
                cursor={{ strokeDasharray: "3 3" }}
                formatter={(value, name) => {
                  if (name === "Insured share") return [`${value}%`, name];
                  if (name === "Revenue proxy") return [`$${value}B`, name];
                  return [value, name];
                }}
                labelFormatter={(_, payload) =>
                  payload?.[0]?.payload?.label ?? "Band"
                }
              />
              <Scatter name="Size bands" data={SIZE_SHARE_SCATTER} fill={COLORS.insured}>
                {SIZE_SHARE_SCATTER.map((p) => (
                  <Cell
                    key={p.label}
                    fill={
                      p.label.startsWith("SME")
                        ? COLORS.insured
                        : p.label.startsWith("Large")
                          ? COLORS.cash
                          : COLORS.accent
                    }
                  />
                ))}
              </Scatter>
            </ScatterChart>
          </ResponsiveContainer>
        ) : null}

        {panel === "sector-pressure" ? (
          <ResponsiveContainer width="100%" height={360}>
            <BarChart
              data={SECTOR_PRESSURE}
              margin={{ top: 8, right: 12, left: 0, bottom: 0 }}
            >
              <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
              <XAxis dataKey="short" tick={{ fill: "#64748b", fontSize: 12 }} />
              <YAxis
                tick={{ fill: "#64748b", fontSize: 12 }}
                domain={[0, 1.6]}
                tickFormatter={(v) => `${v.toFixed(1)}??`}
              />
              <Tooltip
                formatter={(value, _n, item) => [
                  `${Number(value).toFixed(2)}?? relative severity`,
                  item.payload.biHeavy ? "BI-heavy" : "Lower BI weight",
                ]}
                labelFormatter={(_, payload) => payload?.[0]?.payload?.sector ?? ""}
              />
              <Bar dataKey="relativeSeverity" name="Relative severity" radius={[4, 4, 0, 0]}>
                {SECTOR_PRESSURE.map((s) => (
                  <Cell
                    key={s.sector}
                    fill={s.biHeavy ? COLORS.cash : COLORS.insured}
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        ) : null}
      </ChartCard>

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

