                  offset: -4,
                  fill: "#94a3b8",
                  fontSize: 11,
                }}
              />
              <YAxis
                type="number"
                dataKey="insuredSharePct"
                name="Insured share"
                domain={[0, 80]}
                tick={{ fill: "#64748b", fontSize: 12 }}
