args.command:
@'
const fs = require("fs");
const t = fs.readFileSync("src/data/posts.ts", "utf8");
const startMarker = 'slug: "ransomware-payments-vs-uninsured-losses-2026"';
const start = t.indexOf(startMarker);
const contentKey = t.indexOf("content: `", start);
const open = contentKey + "content: `".length;
// find matching close: first `\n  },\n  {\n after open that is the end of this post object
const endFence = t.indexOf("\n  },\n  {\n    id:", open);
const c = t.slice(open, endFence);
console.log({ words: c.trim().split(/\s+/).length, h2: (c.match(/^## /gm) || []).length, chars: c.length });
console.log(c.slice(0, 80));
console.log("---");
console.log(c.slice(-120));
'@ | Set-Content -Encoding utf8 tmp-wc3.cjs; node tmp-wc3.cjs; Remove-Item tmp-wc3.cjs

